def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = rng.uniform(lb, ub, size=dim)
    T = 1000
    alpha = 0.99
    for _ in range(budget):
        y = x + rng.normal(size=dim) * 0.1
        y = clip(y)
        delta = func(y) - func(x)
        if delta < 0 or np.random.rand() < np.exp(-delta / T):
            x = y
            T *= alpha
    return x
